			`,
			expr:                       "increase(series_count[1m1s])",
			typeAndUnitLabelsEnabled:   false,
			expectedWarningAnnotations: []string{},
			expectedInfoAnnotations:    []string{},
		},
		"no info annotation when increase() over series with _bucket suffix": {
			data: `
